if(!side){const nav=wrap(main,'Main navigation','HORIZONTAL',iw(main),'sage',8,0);nav.cornerRadius=WIRE?0:24;nav.layoutWrap='WRAP';nav.counterAxisSpacing=8;for(const label of menus[s.role]){const n=instance(nav,'Navigation item',{Label:label});n.name='Nav / '+label;}}
text(main,WIRE?s.title.replaceAll('\n',' '):s.title,'heading');if(!WIRE)text(main,s.sub,'body','muted');else skeleton(main,1);if(s.note)text(main,s.note,'caption','muted');content(main,s);
const foot=wrap(root,'Footer','HORIZONTAL',1152,null,16,24);text(foot,WIRE?'Footer':'Campus Mate · Your next chapter.','caption','muted',760);for(const label of ['Privacy','Terms','Support']){const n=text(foot,label,'caption','muted',75);n.name='Link / '+label;}return root;
